sys_script_include.script:
var CreateValidateSoftwareModelTask = Class.create();
CreateValidateSoftwareModelTask.prototype = {
    initialize: function () {},

    createTask: function () {
        // Fetch sys_property value
        var sysPropValue = gs.getProperty("validate.property");
        if (!sysPropValue) {
            gs.info("❌ System Property 'validate.property' not found.");
            return "System Property not found.";
        }

        var taskDetails;
        try {
            taskDetails = JSON.parse(sysPropValue);
        } catch (e) {
            gs.error("❌ Error parsing JSON from sys_property: " + e);
            return "Error parsing system property.";
        }

        if (!taskDetails.Validate_Software_Model) {
            gs.info("❌ 'Validate_Software_Model' entry missing in sys_property.");
            return "No task details found.";
        }

        // Create task in samp_sp_vb_task
        var task = new GlideRecord('samp_sp_vb_task');
        task.initialize();
        task.short_description = taskDetails.Validate_Software_Model.short_description;
        task.description = taskDetails.Validate_Software_Model.description;
        task.work_notes = taskDetails.Validate_Software_Model.instruction;
        task.state = "1"; // Open
        task.insert();

        gs.info("✅ Task created in samp_sp_vb_task for Validate Software Model.");
        return "Task created successfully.";
    },

    type: 'CreateValidateSoftwareModelTask'
};
